query GetResourceSeo($id: ID!) {
      node(id: $id) {
        __typename
        ... on Product    { title seo { title description } }
        ... on Collection { title seo { title description } }
        ... on Article {
          title
          titleTag: metafield(namespace: "global", key: "title_tag") { value }
          descriptionTag: metafield(namespace: "global", key: "description_tag") { value }
        }
        ... on Page {
          title
          titleTag: metafield(namespace: "global", key: "title_tag") { value }
          descriptionTag: metafield(namespace: "global", key: "description_tag") { value }
        }
      }
    }
